/// The contents of the FIRST quoted string starting at the head of `s` (single or double quote).
pub(crate) fn quoted(s: &str) -> Option<String> {
    let q = s.chars().next()?;
    if q != '"' && q != '\'' {
        return None;
    }
    let rest = &s[1..];
    rest.find(q).map(|end| rest[..end].to_string())
}
